WITH enriched AS (SELECT *, LAG(budget) OVER (PARTITION BY dept_name ORDER BY budget, id) AS prev_budget, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget, id) AS seq_no, LAG(budget, 1) OVER (PARTITION BY dept_name, location ORDER BY budget, id) AS prev_budget_2 FROM departments WHERE budget <= 3153000) SELECT CASE WHEN prev_budget_2 >= 3951000 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_budget_2_tier, CASE WHEN seq_no >= 8 THEN 'LARGE' ELSE 'SMALL' END AS seq_no_tier, SORT_ARRAY(COLLECT_SET(location)) AS location_list, SUM(seq_no) FILTER (WHERE location = 'London') AS london_total_seq_no FROM enriched GROUP BY CASE WHEN prev_budget_2 >= 3951000 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN seq_no >= 8 THEN 'LARGE' ELSE 'SMALL' END;
